public int jumpingOnClouds(int[] c) {
    int n = c.length;
    int i = 0;
    int jumps = 0;
    while (i < n - 1) {
        if (i + 2 < n && c[i + 2] == 0) {
            i += 2;
        } else {
            i += 1;
        }
        jumps++;
    }
    return jumps;
