public int jumpingOnClouds(int[] c) {
    int n = c.length;
    int[] dp = new int[n];
    final int INF = Integer.MAX_VALUE / 2;
    java.util.Arrays.fill(dp, INF);
    dp[0] = 0;
    for (int i = 1; i < n; i++) {
        if (c[i] == 1) continue;
        int best = dp[i - 1];
        if (i >= 2) best = Math.min(best, dp[i - 2]);
        dp[i] = best + 1;
    }
    return dp[n - 1];
}

