def jumpingOnClouds(self, c: list[int]) -> int:
    n = len(c)
    INF = float('inf')
    dp = [INF] * n
    dp[0] = 0
    for i in range(1, n):
        if c[i] == 1:
            continue
        best = dp[i - 1]
        if i >= 2:
            best = min(best, dp[i - 2])
        dp[i] = best + 1
